"""Deterministic tests for the local slugify function.

Purpose: verify the observable text-to-slug behavior of ``slugify``.
Responsibility: cover ordinary text, separators, boundaries, Unicode, and
invalid input without external services. Assumption: tests run with unittest.
AI assistance: this file was produced with AI assistance.
Copyright: Copyright 2024 the project authors.
"""

import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_normal_text_becomes_lowercase_words(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_whitespace_punctuation_and_repeated_separators_collapse(self):
        self.assertEqual(slugify("  A--B / C!!  "), "a-b-c")

    def test_empty_and_separator_only_input_is_empty(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify("--- ... ___"), "")

    def test_unicode_letters_and_numbers_are_preserved(self):
        self.assertEqual(slugify("Café 東京 42"), "café-東京-42")

    def test_nfkc_normalization_and_casefolding_are_applied(self):
        self.assertEqual(slugify("ＡＢＣ Straße"), "abc-strasse")

    def test_non_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            slugify(None)


if __name__ == "__main__":
    unittest.main()

